import ast, sys

# Extract all async def method signatures from MCP files
mcp_files = {
    'billing': 'src/mcp/billing/billing_mcp.py',
    'catalogue': 'src/mcp/catalogue/catalogue_mcp.py',
    'inventory': 'src/mcp/inventory/inventory_mcp.py',
    'khata': 'src/mcp/khata/khata_mcp.py',
    'identity': 'src/mcp/identity/identity_mcp.py',
    'analytics': 'src/mcp/analytics/analytics_mcp.py',
}

signatures = {}
for domain, fpath in mcp_files.items():
    with open(fpath, encoding='utf-8') as fh:
        tree = ast.parse(fh.read())
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, (ast.AsyncFunctionDef, ast.FunctionDef)):
                    if item.name.startswith('_'):
                        continue
                    args = [a.arg for a in item.args.args if a.arg != 'self']
                    defaults_count = len(item.args.defaults)
                    required = args[:len(args)-defaults_count] if defaults_count else args
                    optional = args[len(args)-defaults_count:] if defaults_count else []
                    key = f'{domain}.{item.name}'
                    signatures[key] = {'required': required, 'optional': optional, 'all': args}

# Now check all wrapper calls in tool_registry.py
with open('src/agent/tool_registry.py', encoding='utf-8') as fh:
    registry_src = fh.read()
    registry_tree = ast.parse(registry_src)

print('=== MCP METHOD SIGNATURES ===')
for key in sorted(signatures):
    s = signatures[key]
    print(f'  {key}({', '.join(s[\"all\"])})')

print()
print('=== CHECKING WRAPPER CALLS ===')
issues = []
for node in ast.walk(registry_tree):
    if isinstance(node, ast.Await):
        call = node.value
        if isinstance(call, ast.Call):
            func = call.func
            if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Attribute):
                # mcps.domain.method(...)
                if isinstance(func.value.value, ast.Name) and func.value.value.id == 'mcps':
                    domain = func.value.attr
                    method = func.attr
                    key = f'{domain}.{method}'
                    if key in signatures:
                        passed_kwargs = {kw.arg for kw in call.keywords if kw.arg}
                        passed_positional = len(call.args)
                        sig = signatures[key]
                        all_params = sig['all']
                        required = sig['required']
                        # Check for extra kwargs not in signature
                        for kwarg in passed_kwargs:
                            if kwarg not in all_params:
                                issues.append(f'  LINE {node.lineno}: {key}() - unexpected kwarg \"{kwarg}\" (not in signature {all_params})')
                        # Check for missing required params
                        for req in required:
                            positional_covered = req == all_params[passed_positional - 1] if passed_positional > 0 else False
                            if req not in passed_kwargs and not positional_covered:
                                issues.append(f'  LINE {node.lineno}: {key}() - required param \"{req}\" not passed')
                    else:
                        pass  # method not found in signatures dict (may be private/not a class method)

if issues:
    print('POTENTIAL ISSUES:')
    for i in issues:
        print(i)
else:
    print('  No unexpected kwargs or missing required params found.')
" 2>&1

