-- 003_create_utility_functions.sql
-- Shared trigger functions used by all tables
-- Run AFTER 002
-- ============================================================

-- Auto-update updated_at whenever a row is modified
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Prevent UPDATE or DELETE on immutable tables
-- (bills, bill_items, khata_entries, stock_movements)
CREATE OR REPLACE FUNCTION prevent_immutable_record_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION
        'Records in table "%" are immutable. Updates and deletes are not allowed.',
        TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

-- Enforce that loose items always have 0% GST
CREATE OR REPLACE FUNCTION enforce_loose_item_gst()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.is_loose = TRUE AND NEW.gst_rate != 0 THEN
        RAISE EXCEPTION
            'Loose items must have 0%% GST. Received gst_rate = %',
            NEW.gst_rate;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

