                    required = args[:len(args)-defaults_count] if defaults_count else args
                    optional = args[len(args)-defaults_count:] if defaults_count else []
                    key = f'{domain}.{item.name}'
                    signatures[key] = {'required': required, 'optional': optional, 'all': args}

