    if isinstance(node, ast.Await):
        call = node.value
        if not isinstance(call, ast.Call):
            continue
        func = call.func
        if not (isinstance(func, ast.Attribute) and isinstance(func.value, ast.Attribute)):
            continue
        if not (isinstance(func.value.value, ast.Name) and func.value.value.id == 'mcps'):
            continue
        domain = func.value.attr
        method = func.attr
        key = f'{domain}.{method}'
        if key not in signatures:
            continue
        passed_kwargs = {kw.arg for kw in call.keywords if kw.arg}
        sig = signatures[key]
        all_params = sig['all']
        required = sig['required']
        # Check for unexpected kwargs
        for kwarg in sorted(passed_kwargs):
            if kwarg not in all_params:
                issues.append(f'  LINE ~{node.lineno}: {key}() — UNEXPECTED kwarg "{kwarg}"  (valid params: {all_params})')
        # Check for missing required params (only kwargs-based check, ignores positional)
        for req in required:
            if req not in passed_kwargs and len(call.args) == 0:
                issues.append(f'  LINE ~{node.lineno}: {key}() — MISSING required param "{req}"')

if issues:
    print(f'FOUND {len(issues)} issue(s):')
    for i in issues:
        print(i)
else:
    print('  No unexpected kwargs or missing required params found.')

